#!/usr/bin/env bash
# The terminal sessions quoted in lesson 9 of node, as a script that produces
# them. Its output is pasted into the lesson by lab/fill.py and not committed.
#
#   sudo bash captures.sh > /tmp/l9.txt && for f in *.md; do python3 ../../lab/fill.py $f /tmp/l9.txt; done
#
# Starts from the links project as lesson 8 left it. Files the lesson shows
# whole are taken out of its .md by lab/shown.py; the edits to admin.js and
# store.js are the sed lines the lesson shows. The admin key is generated by
# the line the lesson shows, so it differs on every run. Servers run "in a
# second terminal" and are stopped afterwards.
set -uo pipefail
cd "$(dirname "$0")"
. ../../lab/lib.sh
L='~/server/links'
quiet $L 'rm -rf .git .env data test/tmp demo.env && printf "node_modules/\ndata/\n" > .gitignore'
for f in src/config.js:parsing-config server.js:parsing-config .env.example:env-files test.env:per-environment count.js:argv; do
  shown ${f#*:}.md ${f%%:*} $L/${f%%:*}
done
# lesson 7's admin.js and lesson 8's store.js, which the sed lines below edit
shown ../le-p24frdep/the-links-app.md src/admin.js $L/src/admin.js
shown ../le-v6za3m0m/atomic-writes.md src/store.js $L/src/store.js
quiet $L 'unset PORT REGION'

block env
session $L "node -p 'process.env.HOME'" "PORT=4000 node -p 'process.env.PORT'" 'echo "the shell: [$PORT]"' \
  "node -p 'process.env.NOTHING'" "EMPTY= node -p 'JSON.stringify(process.env.EMPTY)'" \
  "DEBUG=false node -p 'process.env.DEBUG ? \"truthy\" : \"falsy\"'" 'export REGION=sa-east' "node -p 'process.env.REGION'"
block envfile
session $L "printf 'PORT=4000\nGREETING=hello from the file\n' > demo.env" \
  "node --env-file=demo.env -p 'process.env.PORT + \" \" + process.env.GREETING'" \
  "PORT=5000 node --env-file=demo.env -p 'process.env.PORT'" \
  "node --env-file=missing.env -p 'process.env.PORT'" "node --env-file-if-exists=missing.env -p 'process.env.PORT'" \
  'rm demo.env'
block sed
session $L "sed -i 's|^const ADMIN_KEY = .*|const ADMIN_KEY = config.adminKey;|; s|^import { timingSafeEqual } from \"node:crypto\";|&\\nimport { config } from \"./config.js\";|' src/admin.js" \
  "sed -i 's|^const file = .*|const file = config.dataFile;|; s|^import { makeCode } from \"./code.js\";|&\\nimport { config } from \"./config.js\";|' src/store.js" \
  'grep -n config src/admin.js src/store.js'
block refuse
session $L 'node server.js; echo "exit code $?"' 'PORT=80a ADMIN_KEY=short node server.js; echo "exit code $?"'
block key
session $L "node -p 'require(\"node:crypto\").randomBytes(24).toString(\"base64url\")'" \
  "echo \"ADMIN_KEY=\$(node -p 'require(\"node:crypto\").randomBytes(24).toString(\"base64url\")')\" > .env"
block git
session $L "git init -q && printf '.env\ntest/tmp/\n' >> .gitignore && cat .gitignore" 'git check-ignore -v .env data/links.json' \
  'git status --short'
bg links $L 'node --env-file=.env server.js'; wait_port 3000
block start
bg_show links
block keys
session $L "curl -s -H 'x-admin-key: change-me-in-lesson-9' http://127.0.0.1:3000/links" \
  "curl -s -H \"x-admin-key: \$(sed -n 's/^ADMIN_KEY=//p' .env)\" http://127.0.0.1:3000/links"
bg_stop links INT
block scripts
session $L "npm pkg set scripts.start='node --env-file-if-exists=.env server.js'" \
  "npm pkg set scripts.dev='node --env-file-if-exists=.env --watch server.js'" \
  "npm pkg set scripts.test='node --env-file=test.env --test --test-reporter=spec'" 'ls data'
block tests
session $L 'npm test 2>&1 | grep -E "^(✔|✖|ℹ (tests|pass|fail))"' 'ls data test/tmp'
block tz
session $L "node -p 'new Date(\"2026-10-01T12:00:00Z\").toString()'" \
  "TZ=Asia/Tokyo node -p 'new Date(\"2026-10-01T12:00:00Z\").toString()'" \
  "node -p 'new Date(\"2026-10-01T12:00:00Z\").toISOString()'" \
  "NODE_OPTIONS=--max-old-space-size=40 node -e 'const a = []; for (;;) a.push(new Array(1e6).fill(0))' 2>&1 | grep -E 'FATAL|heap limit'"
block count
quiet $L "curl -s -o /dev/null http://127.0.0.1:1 || true"
bg links2 $L 'npm start'; wait_port 3000
quiet $L "for u in https://nodejs.org/ https://expressjs.com/ https://example.com/; do curl -s -o /dev/null -H 'content-type: application/json' -d \"{\\\"url\\\": \\\"\$u\\\"}\" http://127.0.0.1:3000/links; done"
CODE=$(bash "$LAB_SH" script "cd ~/server/links; curl -s -H \"x-admin-key: \$(sed -n 's/^ADMIN_KEY=//p' .env)\" http://127.0.0.1:3000/links" | python3 -c 'import json,sys; print(json.load(sys.stdin)[0]["code"])')
quiet $L "curl -s -o /dev/null http://127.0.0.1:3000/$CODE; curl -s -o /dev/null http://127.0.0.1:3000/$CODE"
bg_stop links2 INT
session $L 'node count.js --help' 'node count.js' 'node count.js --min 1' 'node count.js --file test/tmp/links.json' \
  'node count.js --minimum 1 2>&1 | grep TypeError'
